function moveAI(e){
  e.cds = e.cds || {}; for(const k in e.cds) if(e.cds[k] > 0) e.cds[k]--;
  let opts = (e.moves || []).filter(m => moveOK(e, m));
  if(!opts.length) opts = (e.moves || []).filter(m => m.dmg) || e.moves;
  const w = m => { let x = m.w || 1; if(e.lastName === m.name) x *= m.dmg ? .6 : .25;
    if(e.ecls === 'berserker' && m.dmg) x *= 2; if(m.if === 'hurt') x *= 1.5;
    if(m.atk === 'front') x *= ['tank','berserker','special'].includes(e.ecls) ? 1.7 : 1.3; else if(m.atk === 'back') x *= 0.8; else if(m.atk === 'pierce') x *= 0.75;   // Nahkämpfer öfter Front, Pierce seltener
    return x; };
  const tot = opts.reduce((s, m) => s + w(m), 0); let r = rng() * tot, pickM = opts[0];
  for(const m of opts){ r -= w(m); if(r <= 0){ pickM = m; break; } }
  if(pickM.cd) e.cds[pickM.name] = pickM.cd + 1;
  const it = {};
  for(const [k, v] of Object.entries(pickM)) if(!['w','if','cd','minTier','up'].includes(k)) it[k] = v;
  (pickM.up || []).slice(0, biomeTier()).forEach(u => { for(const [k, v] of Object.entries(u)){
    if(typeof v === 'number'){ if(k === 'dmg' && !it.dmg) continue; if(k === 'heal'){ ['healLow','healAllies','healSelf'].forEach(h => { if(it[h]) it[h] += v; }); continue; } it[k] = (it[k] || 0) + v; } else it[k] = v; } });
  return it;
}

