ferry.__fn:
async (ev, a, h) => {
  if(a.op !== 'coin') return 'next';
  const tgt = S.heroes[a.tgt], C = FERRY[a.coin]; if(!h || !tgt || tgt.dead || !C || ev.coins[tgt.id] || h.gold < C.price) return;
  h.gold -= C.price; ev.coins[tgt.id] = {coin:a.coin, payer:h.id};
  S.ferry = S.ferry || {}; S.ferry[tgt.id] = {coin:a.coin, biome:S.biomeIdx};
  floatText(h, `-${C.price} Gold`, 'dmg'); toast(`${tgt.name} carries a ${C.name}${h !== tgt ? ` (paid by ${h.name})` : ''}`);
  updateUnit(h); updateUnit(tgt); updateCounters();
}

embrace.__fn:
async (ev, a, h) => {
  if(a.op !== 'drink') return 'next';
  if(!h || h.dead || ev.volunteer) return;
  if(a.v === 'embrace' && S.embraced) return;
  ev.volunteer = h.id; ev.choice = a.v; const sn = GXS();
  if(a.v === 'taste'){ const d = Math.round(h.maxHp * .1); h.taste = S.biomeIdx; h.tasteHp = d; evLoseMax(h, d); GXE(sn, {title:'A taste of blood', theme:'crimson', notes:[`${h.name}: heal 15% of the damage dealt until the biome boss`]}) || toast(`${h.name} took a taste – lifesteal until the end of the biome`); }
  if(a.v === 'embrace'){ const d = Math.round(h.maxHp * .2); evLoseMax(h, d); h.embrace = true; S.embraced = h.id; GXE(sn, {title:'The Crimson Embrace', theme:'crimson', notes:[`${h.name}: forever +1 damage and heal 1 HP per hit`, 'Campfires heal only 15% · Sun-Sick in the desert']}) || toast(`${h.name} accepted the Embrace`); }
  updateUnit(h);
  return ev2Finish();
}

