  const bear = (x, y, c, s, r) => `<g transform="translate(${x} ${y}) scale(${s} ${s * .55}) rotate(${r})" fill="${c}" opacity="${(.45 + s * .35).toFixed(2)}"><path d="M-11 4 Q-12 -6 0 -6 Q12 -6 11 4 Q10 14 0 14 Q-10 14 -11 4Z"/><circle cx="-11" cy="-10" r="3.4"/><circle cx="-5" cy="-14" r="3.4"/><circle cx="2" cy="-15" r="3.4"/><circle cx="9" cy="-13" r="3.4"/><circle cx="13" cy="-7" r="3"/></g>`;
  const feather = (x, y, c, s, r) => `<g transform="translate(${x} ${y}) scale(${s} ${s * .6}) rotate(${r})" opacity="${(.45 + s * .35).toFixed(2)}"><path d="M0 14 Q-9 0 0 -16 Q9 0 0 14Z" fill="${c}"/><path d="M0 18 V-14" stroke="#0a1a16" stroke-width="1.4"/><path d="M0 4 l-6 -4 M0 -4 l6 -4 M0 8 l6 -3" stroke="#0a1a16" stroke-width="1"/></g>`;
  /* Wolf: Pfoten · Bär: breite Tatzen · Schlange: geschlängelte Spur · Falke: verstreute Federn – alle flach auf dem Boden, von vorne in den Wald */
  [['#ff6a5a', 90, paw], ['#5a8aff', 470, bear], null, ['#ffd25a', 1190, feather]].forEach((T, k) => { if(!T) return; const [c, ex, f] = T;
    const n = f === feather ? 6 : 9;
    for(let i = 0; i < n; i++){ const t = i / (n - 1), x = 640 + (ex - 640) * t + (f === feather ? (R() - .5) * 40 : (i % 2 ? 9 : -9)) * (1 - t * .6), y = 712 - t * 136, sc = 1.5 - t * 1.05;
      tracks += f(x.toFixed(0), y.toFixed(0), c, sc.toFixed(2), f === feather ? (R() * 160 - 80).toFixed(0) : Math.atan2(-136, ex - 640) * 180 / Math.PI + 90); } });
  { let d = '', w = ''; for(let i = 0; i <= 40; i++){ const t = i / 40, bx = 640 + (820 - 640) * t, y = 712 - t * 136, amp = 26 * (1 - t * .75), x = bx + Math.sin(t * 14) * amp; d += `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)} `; }
